package com.atlaspay; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.UUID; @RestController @RequestMapping("/v1/authorizations") class AuthorizationController { private final AuthorizationService service; AuthorizationController(AuthorizationService service){this.service=service;} @PostMapping public ResponseEntity<AuthorizationResponse> authorize(@RequestHeader("Idempotency-Key") @NotBlank String key,@Valid @RequestBody AuthorizationRequest request){ return ResponseEntity.ok(service.authorize(key,request)); } record AuthorizationRequest(@NotBlank String paymentId,@NotBlank String issuerId,@Positive long amountMinor,@Pattern(regexp="[A-Z]{3}") String currency){} record AuthorizationResponse(UUID decisionId,String paymentId,String status,String reason){}}